/* Generated by .scratch/tmp/zc/fontgen.mjs from the HTML game UI text.
 * Bitmap masks use the same SimSun rasterization and alpha threshold as
 * zombie-cannon.html, so the LVGL build keeps the same CJK shapes. */
#ifndef ZC_CJK_FONT_H
#define ZC_CJK_FONT_H

#include <stdint.h>

typedef struct {
    uint32_t cp;
    uint16_t data_off;
    uint8_t adv;
    uint8_t w;
    uint8_t h;
    int8_t xoff;
    int8_t yoff;
} zc_glyph_t;

const zc_glyph_t * zc_cjk_lookup(uint32_t cp, int px);
const uint8_t * zc_cjk_bits(void);
int zc_cjk_size_for(int px);

#endif /* ZC_CJK_FONT_H */
